insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 1, 'What does blendDistillationCurves hold fixed on each row of the blend''s curve, and what does it weight?', '["It holds the temperature fixed and weights the crudes'' volume percents there by volume share.", "It holds the volume percent fixed and weights the crudes'' temperatures there by volume share.", "It holds the temperature fixed and weights the crudes'' volume percents there by mass share.", "It holds the volume percent fixed and weights the temperatures by mass share, since mass is conserved."]'::jsonb, 0, 'Yields are additive on volume: at 720 F Kwale Light has distilled 70.0000 percent, Ughelli Medium 56.6667 percent, and the blend at 55 and 45 has distilled 64.0000 percent.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 2, 'On the Kwale blend''s curve, which crude was measured at 265 F, and what does the blend read there?', '["Kwale Light, measured at 18.3333 percent, with Ughelli Medium read at 10 and the blend at 14.5833 percent.", "Ughelli Medium, measured at 10 percent, with Kwale Light read at 18.3333 and the blend at 25.3953 percent.", "Ughelli Medium, measured at 10 percent, with Kwale Light read at 18.3333 and the blend at 14.5833 percent.", "Both crudes were measured at 265 F, and the blend''s 14.5833 percent is their volume-weighted sum on that row."]'::jsonb, 2, 'Ughelli Medium''s assay carries 10 at 265. Kwale Light has no point there and is read between its own points at 190 and 370 F. The blend at 370 F reads 25.3953 percent.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 3, 'A TBP volume percent is weighted by volume share when two crudes are blended. What is the reason?', '["Volume is conserved on mixing and mass is not, so every property of a blend, sulfur included, has to be weighted on volume shares.", "A TBP figure is a volume percent distilled, and the digest''s rule is that yields are additive on volume.", "The engine holds no gravity for a crude at the curve step, so a volume share is the only weight it can form for the yields there.", "A volume weighting gives the larger blend yield at every temperature, which is the conservative reading."]'::jsonb, 1, 'The digest''s rule: yields are additive on volume, so at any temperature the blend has distilled the volume-weighted sum of what each crude has distilled. Sulfur and the other per-mass properties blend on mass. The engine can weight yields on mass too: module 3 prints blendOnMass beside the engine''s cut yields.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 4, 'How many points does the Kwale blend''s curve carry, and where do they come from?', '["11, the temperatures both crudes measured once the ends that neither curve covers are dropped.", "8, the temperatures at which both crudes were measured at round volume percents of their own.", "14, one point per volume percent the two laboratories reported, with the two crudes'' temperatures averaged at each.", "14, every temperature either crude measured, from 75 F to 1470 F."]'::jsonb, 3, 'blendDistillationCurves forms the blend''s curve at every temperature any component measured. Kwale Light was measured at 75, 190, 370, 530, 720, 1030 and 1350 F and Ughelli Medium at 90, 265, 480, 650, 860, 1200 and 1470 F.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 5, 'At 90 F Kwale Light has no measured point. What does the engine read for it there, and how?', '["1.3043 percent, read linearly between its own points 0 at 75 and 10 at 190.", "0.0000 percent, because a crude with no point at a temperature is taken as not yet distilled there.", "0.7174 percent, the blend''s own figure on that row, carried over to each crude that was not measured.", "5.7143 percent, the figure Ughelli Medium''s own curve gives at the next temperature on the blend''s grid."]'::jsonb, 0, 'volumePercentAt is linear between measured points. The blend at 90 F reads 0.7174 percent, Ughelli Medium reads 0.0000 there because its curve starts at 0 at 90, and 5.7143 is Ughelli Medium at 190 F.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 6, 'Ughelli Medium''s first TBP point is 0 at 90. What does the engine read for it at 75 F?', '["Unknown, because 75 F lies outside Ughelli Medium''s measured range, so the row is left out of the blend.", "0.0000 percent, because below a first point at 0 percent nothing has distilled, and the curve says so itself.", "1.3043 percent, the figure Kwale Light''s curve gives at 90 F, taken for the crude that was not measured.", "A value extended back along its first segment from 90 F toward 265 F, which the engine does below any first point."]'::jsonb, 1, 'The row at 75 F prints Kwale Light at 0.0000, Ughelli Medium at 0.0000 and the blend at 0.0000. The curve answers outside its range only where it says so itself.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 7, 'Why does the Kwale blend''s curve start at 75 F and end at 1470 F?', '["Both crudes were measured at 75 F and at 1470 F, so those are the two temperatures their grids have in common.", "The engine draws every blend''s curve on one fixed temperature grid from 75 F to 1470 F, whatever the crudes measured.", "75 F is Kwale Light''s first point and 1470 F is Ughelli Medium''s last, and the blend stands on the union of both grids.", "The engine trims each blend to Ughelli Medium''s grid and adds Kwale Light''s lightest point as a first row."]'::jsonb, 2, 'At 1470 F Kwale Light reads 100.0000 percent: its last point is 100 at 1350, and above a last point at 100 percent everything has distilled. The blend reads 100.0000 there.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 8, 'Beside the Kwale blend''s curve, the digest prints the blend''s properties at 55 and 45. Which set is it?', '["API 32.8173, SG 0.8611 and sulfur 0.2642 wt% on a mass basis.", "API 33.1219, SG 0.8595 and sulfur 0.2268 wt% on a volume basis.", "API 38.4, SG 0.8328 and sulfur 0.11 wt% on a mass basis.", "API 33.1219, SG 0.8595 and sulfur 0.2268 wt% on a mass basis."]'::jsonb, 3, 'The digest prints Blend API 33.1219, SG 0.8595, sulfur 0.2268 wt% (mass basis). 38.4, 0.8328 and 0.11 are Kwale Light''s own figures, and 32.8173, 0.8611 and 0.2642 belong to the Associate tier''s Obigbo export blend.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 9, 'Kwale Light reaches 50 percent at 530 F and Ughelli Medium at 650 F. What does the blend''s curve read at those two temperatures?', '["43.6471 percent at 530 F and 56.9474 percent at 650 F.", "50.0000 percent at both, since each is a crude''s own fifty percent point.", "35.8824 percent at 530 F and 62.6316 percent at 650 F.", "43.6471 percent at 530 F and 64.0000 percent at 650 F."]'::jsonb, 0, 'Neither crude''s own 50 percent temperature is one at which the blend stands at 50 percent. 35.8824 and 62.6316 are the other crude''s figures on those rows, and 64.0000 is the blend at 720 F.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 10, 'Kwale Light is blended 50 and 50 with the Ebocha partial assay, whose curve says nothing below 110 F or above 920 F. What does the engine do at a temperature where Ebocha is unknown?', '["It takes Ebocha as 0 percent distilled there and keeps the temperature on the blend''s curve.", "It leaves that temperature out of the blend''s curve, because the blend''s value there is not known either.", "It keeps the temperature and carries Kwale Light''s figure alone, weighted up to the whole blend.", "It takes Ebocha as 100 percent distilled there, since a partial assay''s missing end is taken as boiled off."]'::jsonb, 1, 'A volume-weighted sum with one unknown term is unknown. The blend''s curve keeps only the temperatures where both crudes are known.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 11, 'How many temperatures did Kwale Light and the Ebocha partial assay measure between them, and how many does the 50 and 50 blend''s curve keep?', '["14 measured, 8 kept.", "11 measured, 11 kept.", "14 measured, 11 kept.", "11 measured, 8 kept."]'::jsonb, 3, 'Of 11 temperatures the two crudes measured between them, the blend''s curve keeps 8. The 14 belongs to the Kwale Light and Ughelli Medium blend, whose assays are whole curves.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 12, 'Which Kwale Light temperatures are missing from the Kwale Light and Ebocha blend''s curve?', '["75, 90 and 1350 F.", "110, 920 and 1350 F.", "75, 1030 and 1350 F.", "1030, 1200 and 1350 F."]'::jsonb, 2, 'Each of 75, 1030 and 1350 F lies outside the stretch from 110 F to 920 F where Ebocha says anything. 90 and 1200 F are Ughelli Medium''s temperatures, and 110 and 920 F are Ebocha''s own and are kept.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 13, 'The Kwale Light and Ebocha blend''s curve starts at 110 F. What does it read there, and why does it not start at 0 percent?', '["3.5217 percent, because Ebocha''s first point is 4 at 110 and how much of it boiled below 110 F is unknown.", "0.0000 percent, because the engine anchors every blend''s curve at 0 percent at its first temperature.", "3.5217 percent, because Kwale Light has not started to distil anywhere below 110 F on its own curve.", "10.2308 percent, the blend''s figure at 190 F, since 190 F is the first temperature both crudes measured."]'::jsonb, 0, 'Kwale Light starts at 0 at 75, so it has distilled below 110 F. Ebocha''s curve reads 4 at 110; 25 at 370; 50 at 590; 70 at 760; 88 at 920, so it neither starts at 0 nor ends at 100.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 14, 'Why does the Kwale Light and Ebocha blend''s curve end at 85.4516 percent instead of running on to 100 percent?', '["Kwale Light''s own curve stops distilling at 920 F, so the blend has nothing left to boil above that temperature either.", "The engine ends every blend''s curve at the last temperature at which the blend is still below 90 percent distilled.", "Ebocha''s missing heavy end is taken as never distilling, so the blend is held at its 920 F figure from there on.", "Ebocha''s last point is 88 at 920, and above it the partial assay says nothing, so no hotter blend row can be known."]'::jsonb, 3, 'A temperature at which some crude''s curve says nothing is left out, because the blend''s value there is not known either. Kwale Light''s rows at 1030 and 1350 F drop out of the partial blend on that rule.'),
  ('crude', 'intermediate', 'module', 'm01-the-blends-own-curve', 15, 'Kwale Light and the Ebocha partial assay are blended 50 and 50. What does the blend''s curve read at 590 F, and whose measured point is 590 F?', '["46.5909 percent, and 590 F is one of Ebocha''s measured points.", "53.1579 percent, and 590 F is one of Kwale Light''s measured points.", "53.1579 percent, and 590 F is one of Ebocha''s measured points.", "67.6471 percent, and 590 F is one of Ebocha''s measured points."]'::jsonb, 2, 'The blend''s row at 590 F reads 53.1579 percent. Ebocha''s curve carries 50 at 590, and Kwale Light was measured at 530 and 720 F. 46.5909 is the blend at 530 F and 67.6471 the blend at 720 F.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 1, 'What does temperatureAtVolumePercent(curve, 50) return for the Kwale blend, Kwale Light and Ughelli Medium at 55 and 45?', '["650 F, the temperature of the first point of the blend''s curve at or past 50 percent, read straight off the grid.", "584.0000 F, the volume-weighted mean of the two crudes'' own 50 percent temperatures at 55 and 45.", "587.3184 F, interpolated between the blend''s own curve points either side of 50 percent.", "586.0503 F, the mass-weighted mean of the two crudes'' own 50 percent temperatures."]'::jsonb, 2, 'The engine reads the blend''s own curve. The grid reading, 650 F, and the two averaged midpoints, 584.0000 F and 586.0503 F, are printed beside it as readings the engine does not use.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 2, 'Between which two points of the Kwale blend''s curve does the engine interpolate to reach its T50?', '["The blend''s own rows at 530 F and 650 F.", "The blend''s own rows at 480 F and 530 F.", "The blend''s own rows at 650 F and 720 F.", "Kwale Light''s own rows at 530 F and 650 F."]'::jsonb, 0, '50 percent lies between 43.6471 at 530 F and 56.9474 at 650 F on the blend''s curve, and the engine''s T50 of 587.3184 F sits on the straight line between them.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 3, 'The Kwale blend''s grid reading of T50 is 650 F. What does that temperature report about the blend?', '["The temperature at which the blend reaches exactly 50 percent, read straight from the grid without the rounding that a straight line between two points would add.", "The temperature at which Kwale Light reaches 50 percent on its own assay, carried over to the blend because Kwale Light holds the larger volume share.", "The volume-weighted mean of the two crudes'' 50 percent temperatures, rounded to the nearest point on the grid.", "The temperature of a grid point at which the blend has already reached 56.9474 percent, which is Ughelli Medium''s own fifty percent point."]'::jsonb, 3, 'At 650 F the blend''s curve reads 56.9474 percent. The grid reading minus the engine is 62.6816 F for the Kwale blend.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 4, 'What does the digest print for the grid reading minus the engine, on the Kwale blend and on the studio''s default pair?', '["72.8571 F on the Kwale blend and 62.6816 F on the default pair.", "62.6816 F on the Kwale blend and 72.8571 F on the default pair.", "-3.3184 F on the Kwale blend and -5.1429 F on the default pair.", "62.6816 F on the Kwale blend and -2.9207 F on the default pair."]'::jsonb, 1, 'The Kwale grid reading is 650 F against 587.3184 F, and the default pair''s is 690 F against 617.1429 F. -3.3184 and -5.1429 F are the volume-weighted means minus the engine, and -2.9207 F is the default pair''s mass-weighted mean minus the engine.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 5, 'Which volume percents make up the digest''s table of other points on the Kwale blend, the T50 row among them?', '["At 0, 25, 50, 75 and 100 percent.", "At each of the 14 points of the blend''s curve.", "At 10, 30, 50, 70 and 90 percent distilled.", "At 50 percent alone, the blend''s T50."]'::jsonb, 2, 'That table has five rows, 10, 30, 50, 70 and 90 percent, and its 50 percent row is the engine''s T50 of 587.3184 F. The blend''s 14 curve points sit at the temperatures the two crudes measured.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 6, 'For the Kwale blend, what is the volume-weighted mean of the crudes'' own T50, and how far does it sit from the engine?', '["584.0000 F, which the digest prints as -3.3184 F against the engine.", "586.0503 F, which the digest prints as -1.2681 F against the engine.", "584.0000 F, which the digest prints as 62.6816 F against the engine.", "612.0000 F, which the digest prints as -5.1429 F against the engine."]'::jsonb, 0, 'The volume-weighted mean of 530 and 650 at 55 and 45 is printed as 584.0000 F. 586.0503 F is the mass-weighted mean, and 612.0000 F belongs to the default pair.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 7, 'The mass-weighted mean of the API numbers is the blend API. Does mass weighting do the same for the Kwale crudes'' own T50?', '["Yes: the digest prints the mass-weighted mean minus the engine as 0.0000 F.", "No: the digest prints the mass-weighted mean minus the engine as 62.6816 F.", "Yes: the mass-weighted mean of the crudes'' T50 is the engine''s 587.3184 F.", "No: the digest prints the mass-weighted mean minus the engine as -1.2681 F."]'::jsonb, 3, 'The Kwale row prints the mass-weighted mean of the crudes'' T50 as 586.0503 F beside the engine''s 587.3184 F, and the difference as -1.2681 F. 62.6816 F is the grid reading minus the engine. The 0.0000 belongs to the mass-weighted mean of the API numbers.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 8, 'For the studio''s default pair, 60 and 40, which volume-weighted and mass-weighted means of the crudes'' T50 does the digest print?', '["584.0000 F and 586.0503 F.", "612.0000 F and 614.2222 F.", "614.2222 F and 612.0000 F.", "612.0000 F and 617.1429 F."]'::jsonb, 1, 'The default pair''s row reads the volume-weighted mean of the crudes'' T50 as 612.0000 F and the mass-weighted mean as 614.2222 F, beside the engine''s 617.1429 F. 584.0000 F and 586.0503 F are the Kwale blend''s.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 9, 'How does the digest establish the offset watsonK adds to a temperature in F?', '["It reads it back from the function: watsonK at 0 F and SG 1, cubed, is 459.6700.", "It types the published Rankine offset of 459.6700 into the digest from a table of constants.", "It bisects watsonK until the function stops returning a value, and takes that temperature.", "It takes the offset as the grid reading minus the engine, 62.6816, scaled onto the Rankine scale."]'::jsonb, 0, 'watsonK = Tb^(1/3) / SG with Tb in degrees Rankine. At SG 1 the division does nothing, so the cube of K is Tb in Rankine, and at 0 F that is the offset the engine gives itself.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 10, 'Which Watson K does the studio report for the Kwale blend, and on what inputs?', '["12.0447, at the grid reading of 650 F and SG 0.8595.", "11.7452, at the T50 of 617.1429 F and SG 0.8727.", "11.8135, at the interpolated T50 of 587.3184 F and SG 0.8595.", "11.8135, at the mean average boiling point and SG 0.8595."]'::jsonb, 2, 'The studio takes Tb as the blend''s T50. 12.0447 is K at the grid reading, and 11.7452 belongs to the studio''s default pair. The mean average boiling point is not computed by the studio.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 11, 'What does watsonK return at -500 F, and at SG 0?', '["A K computed at 0 F in place of -500 F, and no value at SG 0.", "No value at -500 F, and a K on the default pair''s SG 0.8727 at SG 0.", "A K taken on 459.6700 degrees Rankine in both cases.", "No value in either case."]'::jsonb, 3, 'watsonK declines a non-physical input: at -500 F it returns no value, and at SG 0 it returns no value.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 12, 'The studio takes the boiling temperature in Watson K as the blend''s T50. How does this course treat that choice?', '["As a graded figure: Watson K at T50 prints to four decimals, so it is marked like any other four-decimal figure.", "As held item C13, a stated limit: K at T50 is a screening figure and is never graded.", "As a refusal: the studio reports no K until a mean average boiling point is typed in beside the blend''s curve.", "As the strict basis, since the interpolated T50 of a two crude blend is its mean average boiling point."]'::jsonb, 1, 'The studio takes Tb as the blend''s T50, and the page labels K as the screening figure. The digest records that choice as C13, taught here as a stated limit.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 13, 'Which two Watson K figures sit on the default pair''s row, at T50 interpolated and then at the grid reading?', '["11.7452 and 12.0043.", "12.0043 and 11.7452.", "11.8135 and 12.0447.", "11.7452 and 12.0447."]'::jsonb, 0, 'The default pair''s row reads SG 0.8727, Watson K at T50 interpolated 11.7452 and Watson K at the grid reading 12.0043. 11.8135 and 12.0447 are the Kwale blend''s.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 14, 'What does the Kwale valuation downstream of module 2 take from Watson K?', '["The product prices, which the engine scales by K before it sums the cut values, so that a more paraffinic blend nets back more per barrel of crude.", "The cut points, which the engine shifts up or down the blend''s curve in proportion to K before it takes any cut yield off that curve.", "The loss percent, which the engine raises for a lower K on the grounds that an aromatic blend loses more.", "Nothing: the cut yields come from the curve, and the netback from the yields, prices, loss and costs."]'::jsonb, 3, 'cutYields takes each cut as the curve at its upper bound minus the curve at its lower bound, and netback = sum(cut yield fraction x cut product price) x (1 - loss percent / 100) - processing cost - freight. Watson K appears in neither.'),
  ('crude', 'intermediate', 'module', 'm02-the-fifty-percent-point', 15, 'For the studio''s default pair, 60 and 40, which of the four printed T50 readings is read off the blend''s own curve?', '["The 690 F reading printed for the 60 and 40 pair.", "The 617.1429 F reading printed for the 60 and 40 pair.", "The 612.0000 F reading printed for the 60 and 40 pair.", "The 614.2222 F reading printed for the 60 and 40 pair."]'::jsonb, 1, '617.1429 F is the engine''s interpolated T50. 690 F is the first curve point at or past 50 percent, and 612.0000 F and 614.2222 F are the volume-weighted and mass-weighted means of the crudes'' T50.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 1, 'Why does Kwale''s cut set end at atmospheric residue?', '["Neither Kwale crude carries a TBP point above 650 F, so nothing heavier than that can be cut.", "The Kwale refinery has no vacuum unit, so it has nowhere to split the heavy end further.", "The engine closes every cut set with an open residue cut, so no refinery''s set can split it.", "A cut set that splits the residue cannot close on a two crude blend, so the engine joins it."]'::jsonb, 1, 'The digest gives the reason in one line: the Kwale refinery has no vacuum unit, so its cut set ends at atmospheric residue. Kwale draws its own cut points.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 2, 'What is the Kwale blend''s Naphtha yield on Kwale''s cut set?', '["20.4189 volume percent, the two crudes'' naphtha yields weighted by mass fraction.", "22.6185 volume percent, the same blend''s naphtha on the studio''s default cuts.", "24.2512 volume percent, the naphtha yield of Kwale Light, which holds 55 of the barrels.", "20.5591 volume percent, from cutYields on the blend''s own curve."]'::jsonb, 3, 'Kwale''s naphtha runs from 90 F to 330 F. 20.4189 is the mass-weighted reading, 22.6185 is the default set''s naphtha from 90 F to 350 F, and 24.2512 is Kwale Light alone.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 3, 'On Kwale''s cuts, what Diesel / AGO figures does the digest print for the Kwale blend by cutYields on its curve, by blendOnVolume and by blendOnMass?', '["19.3849, 19.3849 and 19.4040.", "19.3849, 19.4040 and 19.4040.", "19.4040, 19.3849 and 19.3849.", "16.9510, 19.3849 and 19.4040."]'::jsonb, 0, 'The Diesel / AGO row reads 19.3849 for the blend by cutYields, 19.3849 volume-weighted from the two crudes, a difference of 0.0000, and 19.4040 mass-weighted from the two crudes. 16.9510 is the blend''s Diesel / Gasoil on the studio''s default cuts.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 4, 'On the Kwale blend, which figure is the engine''s Atmospheric residue yield, and which is the mass-weighted reading beside it?', '["43.2685 is the yield; 43.0526 is the crudes'' yields weighted by volume (blendOnVolume).", "43.0526 is the yield; 43.2685 is the residue on the studio''s default cuts, where it runs to vacuum residue.", "43.0526 is the yield; 43.2685 is the two crudes'' yields weighted by mass fraction (blendOnMass).", "Both are yields: 43.0526 is on volume for the barrels, 43.2685 on mass for pricing by the tonne."]'::jsonb, 2, 'cutYields returns each cut''s yield in volume percent, and the engine''s column is the blend by cutYields on its own curve. 43.2685 sits in the column mass-weighted from the two crudes (blendOnMass). The Kwale blend''s Vacuum residue on the default cuts is 16.3586.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 5, 'Ughelli Medium''s own LPG / Light ends yield on Kwale''s cuts is 0.0000. Why?', '["Its curve starts at 0 percent at 90 F, which is exactly where Kwale''s LPG cut ends.", "Its assay carries no light ends, so the engine enters a zero below any crude''s first point, whatever percent that point is at.", "The engine drops a crude''s LPG cut when its API is below the blend API of 33.1219.", "Its LPG / Light ends yield is unknown, and the engine prints an unknown yield as zero."]'::jsonb, 0, 'None of Ughelli Medium has distilled by the top of that cut. Kwale Light starts at 75 F and has 1.3043 percent by 90 F, and the blend''s 0.7174 carries only Kwale Light''s share.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 6, 'What does Closes: true on the Kwale blend''s cut yields certify?', '["The yields were scaled by the engine to total 100.0000, so every barrel is counted exactly once.", "The blend''s yields match the volume-weighted crude yields on every row with a difference of 0.0000.", "Every cut in the set lies wholly inside the stretch of temperature both crudes measured.", "Every cut has a yield, and together the yields sum to 100.0000, inside the closing tolerance."]'::jsonb, 3, 'Closing needs a yield for every cut and a total inside the engine''s closing tolerance of 100 percent, and the total is not normalised. The 0.0000 difference column is a separate reading of the two routes.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 7, 'The diesel end point is moved from 650 F to 700 F on the Kwale blend. What changes?', '["Diesel / AGO gains 5.0376, and the -5.0376 is spread across Kerosene / DPK and Atmospheric residue by their yields.", "Diesel / AGO gains 5.0376 and Atmospheric residue changes by -5.0376, and every other cut and the total change by 0.0000.", "Diesel / AGO rises to 24.4225 and the total rises by 5.0376, since the new barrels come from past the curve''s end.", "Diesel / AGO gains 5.0376 and Kerosene / DPK changes by -5.0376, since kerosene is diesel''s neighbour on the curve."]'::jsonb, 1, 'The moved temperature is diesel''s top and residue''s bottom, so one quantity is added in one place and subtracted in the other. Atmospheric residue falls from 43.0526 to 38.0150.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 8, 'Why does the total of the Kwale blend''s cut yields change by 0.0000 when the diesel end point moves?', '["The engine normalises the total back to 100.0000 after any cut point moves.", "The moved barrels are taken from the lost volume, which sits outside the total.", "Moving a cut point moves barrels between two cuts and nowhere else.", "The Diesel / AGO gain is small enough that the total rounds back to 100.0000."]'::jsonb, 2, 'The digest prints the rule with the table: moving a cut point moves barrels between two cuts and nowhere else. Diesel / AGO changes by 5.0376, Atmospheric residue by -5.0376 and the total by 0.0000. The total is reported as it computes and is never normalised.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 9, 'In the cut table, which Naphtha and Kerosene / DPK figures stand in the Kwale Light column?', '["24.2512 and 18.1944 volume percent.", "16.0465 and 13.9535 volume percent.", "20.5591 and 16.2860 volume percent.", "24.2512 and 13.9535 volume percent."]'::jsonb, 0, 'The Kwale Light column reads Naphtha 24.2512 and Kerosene / DPK 18.1944. Ughelli Medium''s column reads 16.0465 and 13.9535, and the blend reads 20.5591 and 16.2860.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 10, 'Kwale Light is blended 50 and 50 with the Ebocha partial assay and cut on Kwale''s set. Why do LPG / Light ends and Naphtha come back unknown?', '["Each lies above 920 F, where the blend''s curve stops, so the curve has no value at their upper bounds.", "Ebocha carries no light ends, so the engine marks every cut lighter than kerosene as unknown.", "Their yields fall below the engine''s closing tolerance, so they are reported as unknown.", "Each has a bound below 110 F, where the blend''s curve starts, so the curve has no value at 90 F."]'::jsonb, 3, 'The blend''s curve starts at 110 F and stops at 920 F. unknownCuts: LPG / Light ends, Naphtha.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 11, 'The partial blend''s curve stops at 920 F, yet Atmospheric residue gets a yield of 40.1548. Why?', '["The engine takes Ebocha as wholly distilled above 920 F for the residue cut alone, and so the cut can close.", "The residue yield is the known cuts'' shortfall from 100 percent, carried into the last cut so the set can close.", "It has no upper bound: it runs from its lower bound of 650 F to 100 percent, and 650 F lies inside the curve.", "Kwale Light is known above 920 F, so the residue is valued on Kwale Light''s own residue yield of 37.3684."]'::jsonb, 2, 'A last cut with no upper bound takes everything not yet distilled at its lower bound. Kerosene / DPK, 16.9626, and Diesel / AGO, 19.2202, also sit wholly inside the curve.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 12, 'What does the engine report for the cuts with a yield on the partial blend, and does it scale them?', '["They are scaled up to total 100.0000, spreading the missing barrels over the known cuts.", "They total 76.3376 percent, reported as computed, with no scaling toward 100 percent.", "They total 33.6742 percent, the known cuts of the Ebocha partial assay on the default set.", "They total 76.3376 percent, and the engine scales them only when unknownCuts is empty."]'::jsonb, 1, 'The digest prints: the cuts with a yield total 76.3376 percent, and the total is reported as it computes and is never normalised. 33.6742 belongs to the Ebocha partial assay alone on the studio''s cuts.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 13, 'On the Kwale Light and Ebocha blend cut on Kwale''s set, what do unknownCuts and Closes read?', '["unknownCuts: LPG / Light ends, Naphtha. Closes: false.", "unknownCuts: LPG / Light ends, Naphtha. Closes: true.", "unknownCuts: Atmospheric residue. Closes: false.", "unknownCuts: LPG / Light ends, Naphtha, Vacuum gasoil, Vacuum residue. Closes: false."]'::jsonb, 0, 'The digest prints unknownCuts: LPG / Light ends, Naphtha. Closes: false. Atmospheric residue has a yield, 40.1548, because it runs from 650 F to 100 percent. Four cuts with no yield belong to the Ebocha partial assay alone on the studio''s cuts.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 14, 'Kwale Light and the Ebocha partial assay are valued as a blend on the Kwale refinery''s prices, costs and losses. What comes back?', '["A refusal in place of a figure, because netbackValue will not value any blend whose cut yields do not close, and it names the cuts that stopped it.", "A netback of 48.3393 $/bbl with complete: true, since the missing cuts are already named in unknownCuts and a named gap leaves a valuation whole.", "A netback over the three cuts it can value, with LPG / Light ends and Naphtha entered at a yield of 0.0000 and complete: true.", "A netback of 48.3393 $/bbl over the cuts it can value, with unyieldedCuts naming LPG / Light ends and Naphtha and complete: false."]'::jsonb, 3, 'The digest prints unyieldedCuts: LPG / Light ends, Naphtha beside the 48.3393 $/bbl, and complete: false. Both cuts keep an empty yield and an empty value.'),
  ('crude', 'intermediate', 'module', 'm03-cut-yields-of-the-blend', 15, 'The Kwale blend yields 0.7174 percent LPG / Light ends on Kwale''s cuts and on the studio''s default cuts. Why do the two tables agree on that row?', '["Light ends are fixed by the crudes'' API and do not depend on where any cut point is drawn.", "The engine reports the first cut of every set on the blend''s own grid, whatever its bounds.", "Both cut sets draw it from 0 percent to 90 F, so it is the same stretch of the same curve.", "The default set is Kwale''s set with a vacuum split added, so every cut it shares agrees."]'::jsonb, 2, 'Where a boundary moves, the yields on either side of it move with it: Kerosene / DPK reads 16.2860 on Kwale''s cuts and Kerosene / Jet 16.6604 on the default set.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 1, 'In what order does netbackValue apply its terms?', '["Cut yield fraction times product price, summed; processing cost and freight subtracted; then the result times (1 - loss percent / 100).", "Processing cost and freight subtracted from each product price; each result times its cut yield fraction; then the loss percent taken off the sum.", "Cut yield fraction times product price, summed; that sum times (1 - loss percent / 100); then processing cost and freight subtracted.", "Cut yield fraction times product price, summed; then the loss percent, processing cost and freight each subtracted from the sum in dollars."]'::jsonb, 2, 'Losses are a volume shrinkage on the product side, so they come off the product value before the costs. All terms are per barrel of crude.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 2, 'On the Kwale blend, what is Naphtha''s value per barrel of crude, and what is it formed from?', '["15.2137 $/bbl of crude, its yield of 20.5591 volume percent as a fraction times 74 $/bbl of product.", "15.1460 $/bbl of crude, its yield of 20.5591 volume percent as a fraction times 74 $/bbl of product.", "74 $/bbl of crude, the naphtha price, since a price per barrel of product is a value per barrel of crude.", "15.2137 $/bbl of product, its yield of 20.5591 as a fraction times 74 $/bbl of crude."]'::jsonb, 0, 'Naphtha is 20.5591 percent of every barrel of the Kwale blend, and each of those barrels of product sells at 74. 15.1460 is Kerosene / DPK''s value, 16.2860 percent at 93.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 3, 'What does the cut yield do in the gross product value?', '["It converts a price per tonne of product into a price per barrel of product.", "It weights each product price by the crude''s mass share in that cut.", "It scales the product price for the loss before the costs are taken.", "It converts a price per barrel of product into a value per barrel of crude."]'::jsonb, 3, 'A barrel of the Kwale blend yields 20.5591 volume percent naphtha, so that fraction of every barrel of crude comes out as naphtha at 74 $/bbl of product.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 4, 'Atmospheric residue is priced at 57 $/bbl of product and Diesel / AGO at 98. Why does residue contribute 24.5400 $/bbl of crude against diesel''s 18.9972?', '["Residue carries no processing cost of its own at a topping refinery, so its value is left whole while diesel''s value has the 6.8000 processing cost taken off first.", "Residue is 43.0526 volume percent of the blend against diesel''s 19.3849, and a cut''s contribution is its yield and its price together.", "Residue is sold by the tonne, so the engine values it on its mass-weighted yield of 43.2685, and that heavier basis lifts its contribution over diesel''s.", "Diesel''s value is shrunk by the loss at 0.8 percent and residue''s value is not, since residue loses no volume."]'::jsonb, 1, 'The engine''s formula sums each cut''s yield fraction times its product price, so a cut''s share of the gross of 74.2412 $/bbl of crude rests on both columns.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 5, 'In the Kwale netback, what are the gross product value and the netback the engine reports?', '["74.2412 and 65.0169 $/bbl of crude.", "74.2412 and 67.4412 $/bbl of crude.", "74.2412 and 64.9473 $/bbl of crude.", "49.7012 and 40.6036 $/bbl of crude."]'::jsonb, 2, 'The term table reads gross product value 74.2412 and netback 64.9473 $/bbl of crude. 65.0169 is the netback with losses taken off after the costs, 67.4412 the netback with freight and losses left blank, and 49.7012 and 40.6036 the case with the residue price left blank.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 6, 'In the Kwale netback, what is the value lost to losses, and where does the engine take it?', '["0.5939 $/bbl of crude, off the gross product value before processing and freight.", "0.5939 $/bbl of crude, off the netback after processing and freight have come off.", "0.0696 $/bbl of crude, off the gross product value before processing and freight.", "0.8 $/bbl of crude, the loss percent charged as a cost per barrel beside freight."]'::jsonb, 0, 'A loss of 0.8 percent is a volume shrinkage on the product side. 0.0696 is how far the after-the-costs reading lands from the engine''s netback of 64.9473.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 7, 'If the loss percent is taken off the netback after processing and freight, what does the digest print?', '["65.5412 $/bbl, which is 0.5939 above the engine''s netback.", "64.9473 $/bbl, which is 0.0000 from the engine''s netback.", "65.0169 $/bbl, which is 0.5939 above the engine''s netback.", "65.0169 $/bbl, which is 0.0696 above the engine''s netback."]'::jsonb, 3, 'The engine takes losses off the product value before the costs, and this reading takes them off a figure that already has processing and freight removed. The digest prints it at 65.0169, 0.0696 from the engine''s 64.9473. 65.5412 is the reading with losses left out.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 8, 'Why are processing cost and freight not reduced by the product losses?', '["They are reduced by the losses, and the engine folds that into the value lost.", "They are charged per barrel of crude, and the loss is a shrinkage of the product side only.", "They are taken on mass, and the loss percent is a volume shrinkage only.", "They are blank in the Kwale case, so there is nothing for the loss to reduce."]'::jsonb, 1, 'Processing cost and freight are charged per barrel of crude. In the Kwale case processing is 6.8000 and freight 1.9000 $/bbl, taken off after the value lost to losses of 0.5939.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 9, 'The losses left out reading lands 0.5939 above the engine''s netback. Which figure in the engine''s term table does that match?', '["The distance of the after-the-costs reading from the engine, 0.0696 $/bbl.", "The freight, 1.9000 $/bbl of crude, taken off after the losses.", "The value lost to losses at 0.8 percent, 0.5939 $/bbl of crude.", "The processing cost, 6.8000 $/bbl of crude, taken off before freight."]'::jsonb, 2, 'The losses left out reading is 65.5412 against the engine''s 64.9473, and the digest prints that difference as 0.5939, the figure it also prints as the value lost to losses at 0.8 percent.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 10, 'The engine can return assumedZero, unpricedCuts and unyieldedCuts. Which of them leaves the valuation complete?', '["unpricedCuts: an unpriced cut adds nothing, so the rest stays complete.", "unyieldedCuts: a cut with no yield has no barrels to value, so none are missing.", "All three do, since each list names its gap and a named gap is complete.", "assumedZero: a blank cost is named and the valuation stays complete."]'::jsonb, 3, 'A missing price or a missing yield makes the valuation incomplete: the residue left unpriced gives complete: false, and the partial Ebocha blend''s unyieldedCuts, LPG / Light ends, Naphtha, give complete: false.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 11, 'Kwale is valued with freight and losses left blank. What does the engine return?', '["A netback of 67.4412 $/bbl, assumedZero naming freight and losses, and complete: true.", "A refusal naming freight and losses as costs the netback cannot be formed without.", "A netback of 67.4412 $/bbl with complete: false, since two costs were left blank.", "A netback of 64.9473 $/bbl, since blank costs fall back to the Kwale defaults."]'::jsonb, 0, 'A blank cost is taken as zero and NAMED. The complete Kwale valuation, every field filled, is 64.9473 $/bbl, and only the list beside each figure tells a reader which one they hold.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 12, 'Why does netbackValue take a blank cost as zero instead of refusing?', '["A blank cost is almost always a typing slip, and zero is the least harmful figure to put in its place.", "A netback with no freight is a legitimate question, and the engine names the cost it took as zero.", "The engine holds a default of zero for every input and applies it to any field left empty.", "Refusing would stop the stability screen, which runs inside the same call as the netback."]'::jsonb, 1, 'A blank cost is taken as zero and named. With freight and losses blank the Kwale netback is 67.4412 $/bbl and assumedZero reads freight, losses.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 13, 'A blank freight is taken as zero and named. Why is a blank sulfur treated differently?', '["A blank sulfur is taken as zero as well, and it is named in assumedZero beside any blank cost, so the two blanks are in fact treated alike.", "A blank sulfur is filled from the other crude''s sulfur, and that crude is named as the source of the figure.", "A blank property is treated as absent: the sulfur comes back as no value, and the crude without it is named.", "A blank sulfur is refused outright, since a blend with no sulfur cannot be sold at all."]'::jsonb, 2, 'A blank cost is taken as zero and named in assumedZero. A blank sulfur is absent: the property comes back as no value, and the crude without it is named as missing.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 14, 'Suppose nobody types a price for Atmospheric residue on the Kwale blend. What do the gross, the netback and the engine''s lists read?', '["Gross 49.7012 and netback 40.6036 $/bbl, assumedZero naming the residue price, and complete: true.", "Gross 74.2412 and netback 64.9473 $/bbl, since a blank price falls back to the residue default.", "A refusal, since a netback cannot be formed while any cut in the set is left without a price.", "Gross 49.7012 and netback 40.6036 $/bbl, unpricedCuts naming Atmospheric residue, and complete: false."]'::jsonb, 3, 'A cut with no price contributes nothing and is named, and the valuation reports itself incomplete. The complete Kwale case priced residue at 57 for a value of 24.5400 $/bbl of crude.'),
  ('crude', 'intermediate', 'module', 'm04-netback', 15, 'Why does a blank residue price make the valuation incomplete when a blank freight does not?', '["A cut with no price contributes nothing, so Atmospheric residue, 43.0526 percent of every barrel of crude, goes unvalued in the netback.", "A price is a market figure and a freight is a refinery figure, and the engine trusts only the refinery''s blanks.", "The residue price multiplies the loss, so a blank price leaves the loss term unformed and the netback with it.", "Freight is small beside residue''s value, and the engine marks incomplete only a blank worth more than the loss."]'::jsonb, 0, 'A blank cost is named and does not make the valuation incomplete; a missing price or a missing yield does. complete: false says the 40.6036 figure leaves Atmospheric residue unvalued.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 1, 'How does netbackValue define the differential against a marker?', '["The marker''s netback minus this crude''s netback.", "This crude''s gross product value minus the marker''s netback.", "This crude''s netback over the marker''s netback, as a ratio.", "This crude''s netback minus the marker''s netback."]'::jsonb, 3, 'Kwale''s marker is 72.5 $/bbl. The blend nets back 64.9473 $/bbl and the engine reports the differential as -7.5527 $/bbl.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 2, 'The Kwale blend''s differential against its marker is -7.5527 $/bbl. What does the sign say?', '["The blend nets back more than the marker crude, read on the marker minus crude convention.", "The blend nets back less than the marker, since the differential is this crude''s netback minus the marker''s.", "The blend''s gross product value falls short of the marker''s gross by that figure.", "The blend''s valuation is incomplete, since a negative differential flags a missing term."]'::jsonb, 1, 'The engine''s convention: this crude''s netback minus the marker''s, so a negative differential is a netback below the marker''s. Gross product value and completeness do not enter it.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 3, 'What does netbackValue report for Kwale Light valued alone on Kwale''s terms?', '["Gross 75.2968, netback 65.9944 and a differential of -6.5056 $/bbl.", "Gross 72.9512, netback 63.6676 and a differential of -8.8324 $/bbl.", "Gross 74.2412, netback 64.9473 and a differential of -7.5527 $/bbl.", "Gross 75.2968, netback 65.9944 and a differential of -7.5527 $/bbl."]'::jsonb, 0, 'Each crude alone is valued on the same Kwale cut set, product prices, processing cost, freight and losses as the blend. The blend''s own row reads 74.2412, 64.9473 and -7.5527.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 4, 'Three rows are valued against Kwale''s marker: Kwale Light alone, Ughelli Medium alone and the blend. What makes the rows comparable?', '["Each crude is valued on a cut set of its own, drawn at its own measured temperatures, so the yields show each crude at its best and the rows share a scale.", "Each row''s netback is normalised by its own gross, so crudes of different value can be read on one scale.", "Each is valued on the same Kwale cut set, product prices, processing cost, freight and losses, so only the crude changes.", "Each row is valued against a marker built from that row''s own crude, so each differential is consistent with itself whatever terms the row carries."]'::jsonb, 2, 'One set of terms stands behind all three rows, and every differential here is against the same 72.5 $/bbl.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 5, 'What does netbackValue take from the caller in order to report a differential against a marker?', '["The marker crude''s own TBP assay, which it blends and values on the same cuts before the subtraction is made.", "A marker gross product value, which it sets against this crude''s gross before any cost or loss is taken.", "A marker sulfur and API, from which it prices a quality differential per barrel against this crude.", "A marker netback in $/bbl, such as Kwale''s 72.5, which it sets against this crude''s own netback."]'::jsonb, 3, 'netbackValue takes a marker netback and reports this crude''s netback minus the marker''s. Kwale Light alone reports -6.5056 against the same 72.5.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 6, 'Kwale Light and Ughelli Medium each have a netback of their own. Weighted 55 and 45 on volume, where do they land against the blend''s netback?', '["The mean is 65.0169 $/bbl, and the digest prints the difference as 0.0696.", "The mean is 64.9473 $/bbl, and the digest prints the difference as 0.0000.", "The mean is 64.9473 $/bbl, and the digest prints the difference as -7.5527.", "The mean is 65.5412 $/bbl, and the digest prints the difference as 0.5939."]'::jsonb, 1, 'The blend is worth what its barrels are worth: its netback and the volume-weighted netbacks of its crudes are the same figure.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 7, 'Why does the netback of the Kwale blend equal the volume-weighted mean of its crudes'' netbacks?', '["Yields add on volume and every other term is per barrel, so the blend is worth what its barrels are worth.", "The engine forms the blend''s netback as that mean, so the two figures are one computation printed twice.", "The two crudes carry the same netback, 64.9473 $/bbl each, so any weighting lands on the blend''s figure.", "Netbacks blend on mass, and at 55 and 45 the mass and volume shares of these two crudes coincide."]'::jsonb, 0, 'The blend''s netback is computed from the blend''s own curve, its own cut yields and the full chain. The mean is formed from the two single-crude netbacks, 65.9944 and 63.6676.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 8, 'What does the digest say d86ToTbp has the structure of?', '["A fixed offset added at every point of the D86 curve, with no coefficient table needed.", "A bisection on the D86 curve for the temperature of each TBP point in turn.", "The cut-point-difference conversion, API Technical Data Book Procedure 3A1.1.", "The Refutas index form, blended on volume fraction the way ASTM D7152 blends it."]'::jsonb, 2, 'The digest: d86ToTbp has the structure of the cut-point-difference conversion (API Technical Data Book Procedure 3A1.1) and ships no coefficient table. Called without the table, it refuses.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 9, 'Against Kwale''s marker of 72.5 $/bbl, what differential does netbackValue report for Ughelli Medium valued alone, and what does its sign say?', '["-6.5056 $/bbl: valued alone on Kwale''s terms, Ughelli Medium nets back less than the marker.", "-8.8324 $/bbl: valued alone on Kwale''s cut set and prices, Ughelli Medium nets back below the marker.", "-7.5527 $/bbl: a crude valued alone is reported through the blend''s differential, which it shares.", "63.6676 $/bbl: a crude valued alone carries a netback of its own and no differential against the marker."]'::jsonb, 1, 'The Ughelli Medium alone row reads gross 72.9512, netback 63.6676 and differential -8.8324. -6.5056 belongs to Kwale Light alone and -7.5527 to the blend.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 10, 'On this valuation, does blending Kwale Light and Ughelli Medium create or destroy netback?', '["It destroys netback, because the blend''s Watson K at T50 of 11.8135 marks it as a poorer feed than either crude.", "It destroys netback, because the blend''s loss of 0.5939 is taken on a mixed barrel.", "It creates netback, because the blend''s curve has 14 points where each crude''s assay has fewer.", "Neither: the blend nets back the volume-weighted mean of its crudes'' netbacks."]'::jsonb, 3, 'The digest prints the blend''s netback minus the volume-weighted mean of its crudes'' netbacks as 0.0000, with every row on the same cut set, prices, costs and losses.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 11, 'What does netbackValue return when asked to value with losses of 101 percent?', '["REFUSED: Losses must be between 0 and 100 percent.", "A netback on losses taken as zero, with losses named in assumedZero as a blank would be.", "A netback on a negative product value, with complete: false beside it.", "A netback on losses of 0.8 percent, the last valid figure it was given."]'::jsonb, 0, 'The engine refuses the input and returns no netback. The Kwale figure of 0.8 percent lies inside the range and is valued.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 12, 'Which loss percents does the digest show netbackValue refusing?', '["101 percent only; -1 percent is taken as zero and named in assumedZero.", "-1 percent only; 101 percent is capped at 100 and valued.", "101 percent and -1 percent, each refused with the same sentence.", "Neither; both are valued, with complete: false beside the netback."]'::jsonb, 2, 'The refusal table prints two rows, losses of 101 percent and losses of -1 percent, and one sentence for both: REFUSED: Losses must be between 0 and 100 percent.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 13, 'A blank loss is taken as zero and named. A loss of 101 percent is refused. What separates the two?', '["A blank loss is named in unpricedCuts, and 101 percent is capped at 100 percent.", "A blank loss makes the valuation incomplete, and 101 percent is valued with complete: false.", "Both are refused in the engine; the blank is taken as zero by the studio alone.", "A blank loss is taken as zero in assumedZero; losses must be between 0 and 100 percent."]'::jsonb, 3, 'The digest prints Kwale with freight and losses left blank at 67.4412 $/bbl, assumedZero naming freight, losses, and complete: true. Losses of 101 percent return REFUSED: Losses must be between 0 and 100 percent.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 14, 'A crude arrives with only a D86 curve. What does d86ToTbp return when called without a coefficient table?', '["REFUSED: D86 to TBP conversion needs the API Technical Data Book Procedure 3A1.1 coefficient table, which is not shipped with this package. Supply it, or enter the assay as a TBP distillation, which is how crude assays are reported.", "A TBP curve converted with the package''s own copy of the Procedure 3A1.1 coefficients, with the table''s source named beside the result for the reader to check.", "The D86 curve returned unchanged and labelled as TBP, since the two distillations agree closely enough for a screening valuation on the refinery''s cuts.", "A TBP curve shifted by the published offset at each point, with the curve''s initial and end points held where the D86 test placed them in the laboratory."]'::jsonb, 0, 'D86 is a product test; a crude assay is reported as a TBP distillation. The refusal names two ways forward: supply the table, or enter the assay as a TBP distillation.'),
  ('crude', 'intermediate', 'module', 'm05-against-the-marker', 15, 'Why does d86ToTbp refuse a D86 curve with no 50 percent point, even with a table supplied?', '["The engine reads T50 as the crude''s midpoint for Watson K, and it refuses any curve that cannot supply one.", "The engine anchors the conversion at the 50 percent point, and this D86 curve carries no such point to anchor on.", "A D86 curve with no 50 percent point is a product test, and a crude assay must carry its own T50 point.", "The engine interpolates the 50 percent point from the other points and refuses when the two nearest points are far apart."]'::jsonb, 1, 'The engine returns REFUSED: The D86 curve needs a 50 percent point to anchor the conversion. The method has the structure of the cut-point-difference conversion.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The Kwale valuation opens with a blend API of 33.1219. On what basis did the engine form it?', '["Averaged directly from the two crudes'' API numbers, weighted by volume share.", "Computed from the volume-blended specific gravity, never averaged directly.", "Read off the blend''s own curve at the fifty percent point, then converted.", "Specific gravity weighted by mass fraction from the two crudes, then converted to API."]'::jsonb, 1, 'That basis is the engine''s own words for API. The Kwale blend''s SG is 0.8595.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'In the Kwale valuation, which figure carries the label screening, and why?', '["The blend T50 of 587.3184 F, because an interpolated reading between two curve points is only a screen of the true midpoint.", "The differential of -7.5527 $/bbl, because a marker differential is a screen until the marker''s own terms are checked by a trader.", "The loss value of 0.5939 $/bbl, because a loss percent typed by the refinery is a screen until it is measured across a year.", "Watson K at T50, 11.8135, because T50 stands in for the mean average boiling point, which the studio does not compute."]'::jsonb, 3, 'That choice is held item C13, a stated limit. The page labels K as the screening figure and nothing is graded on it.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Which set of four checks does the digest show the Kwale valuation passing?', '["The yields close; nothing is assumed zero; the loss comes off before the costs; the blend''s netback matches its crudes'' volume-weighted mean.", "The yields close; the blend API matches the volume-weighted mean of the API numbers; the Watson K sits in a paraffinic band; the differential is positive.", "The yields total 100.0000 after scaling; every cost is typed; the loss is taken after the costs; the T50 matches the mean of the crudes'' own T50.", "The curve has a point at every 10 percent; the cut set has a vacuum split; the netback exceeds the marker; the oracle reproduces the Watson K."]'::jsonb, 0, 'In the Kwale case the yields close, the netback of 64.9473 $/bbl is complete with nothing assumed zero, the loss appears as its own term of 0.5939 directly after gross, and the blend minus the mean is 0.0000.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'A learner opens the Crude Assay & Blending Studio with nothing typed and reads a netback of 69.7334 $/bbl. What is it the netback of?', '["The Kwale blend, 55 and 45, on Kwale''s cut set before freight is taken off.", "Kwale Light alone, valued on the studio''s default cuts and default prices.", "The studio''s default pair, 60 and 40, on its default cuts and default valuation.", "The Kwale blend on the studio''s default cuts, with Kwale''s prices kept."]'::jsonb, 2, 'The default table is the studio''s default pair, 60 and 40, on its default cuts and default valuation. The Kwale blend is 55 and 45 and nets back 64.9473 $/bbl on Kwale''s cuts.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The studio''s default table reads stability screen basis api-contrast. What does that say about the SARA behind it?', '["SARA was supplied for both crudes and blended on mass, and the gravity contrast confirmed the colloidal instability index.", "SARA was not supplied for every crude, so the screen falls back to the gravity rule of thumb, which can raise a flag and can never clear one.", "SARA was supplied for every crude, and api-contrast names the engine''s check of the index against the lighter crude''s gravity.", "The SARA fractions were blended on volume, and api-contrast names the volume basis used for the stability screen."]'::jsonb, 1, 'The Associate tier taught the screen: with SARA on every crude the engine forms the colloidal instability index. With SARA on only some crudes, or none, the screen falls back to gravity, which can raise a flag and cannot clear a blend.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'What T50 and Watson K does the studio''s default pair show, and on which basis is the K labelled?', '["T50 690 F from the grid, and Watson K at the grid reading of 12.0043, labelled screening.", "T50 587.3184 F interpolated, and Watson K at T50 of 11.8135, labelled screening.", "T50 617.1429 F interpolated, and Watson K of 11.7452 on the mean average boiling point.", "T50 617.1429 F interpolated, and Watson K at T50 of 11.7452, labelled screening."]'::jsonb, 3, 'The default table prints the blend T50 F (interpolated) as 617.1429 and Watson K at T50 (screening) as 11.7452. 587.3184 and 11.8135 are the Kwale blend''s.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'How is oracle_crudeassay.py written, by the digest''s account?', '["From the rules, independently of the JavaScript engine.", "From the JavaScript engine, translated line for line into Python.", "From the golden files, fitted to reproduce each case.", "From the digest''s own tables, read back as its inputs."]'::jsonb, 0, 'The digest describes an independent Python oracle, tools/validation/downstream/oracle_crudeassay.py, written from the rules, and counts its golden cases from the vendored file.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'How does oracle_crudeassay.py reach a blend''s T50, and how does that road differ from the engine''s?', '["By interpolating between the two points either side of 50 percent, where the engine searches by bisection.", "By the volume-weighted mean of the two crudes'' own T50 figures, where the engine reads the blend''s own curve between two points either side.", "By bisection on the curve for the temperature at which it reaches 50, where the engine interpolates between the two points either side.", "By reading the first curve point at or past 50 percent, where the engine interpolates."]'::jsonb, 2, 'The oracle finds T50 by bisection. The Kwale blend''s T50 is 587.3184 F.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'What form does the Python oracle give the Kwale netback, beside netbackValue''s formula?', '["As the engine''s own per barrel formula rerun line for line in Python, where the engine runs it in JavaScript.", "As the volume-weighted mean of the crudes'' own netbacks, where the engine values the blend''s own cut yields.", "As a gross product value alone, where the engine goes on to take the loss, processing cost and freight off.", "As a 100,000 bbl account on a loaded cargo, where the engine''s formula runs per barrel of crude."]'::jsonb, 3, 'The oracle loads a cargo in barrels and pounds and keeps the netback as a 100,000 bbl account. netbackValue states every term per barrel of crude. The Kwale netback is 64.9473 $/bbl.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What golden cases is oracle_crudeassay.py checked on, counted from the vendored file?', '["4 blends, 6 curve cases and 1 blended default curve.", "6 blends, 4 curve cases and 1 blended default curve.", "6 blends, 4 curve cases and 14 blended curve points.", "11 blends, 8 curve cases and 1 blended default curve."]'::jsonb, 1, 'The golden sets are counted from the vendored file: blends 6, curve cases 4, blended default curve 1.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What does the Python oracle for the assay engine load a blend as?', '["As a cargo, loaded in barrels and in pounds.", "As mass shares from resolveFractions.", "As one barrel at the refinery gate.", "As volume shares normalised to 100."]'::jsonb, 0, 'The digest''s oracle line begins with the load: a cargo in barrels and pounds. The engine itself converts volume shares to mass shares with resolveFractions.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Which Kerosene / Jet and Diesel / Gasoil yields does the studio''s default table print for its default pair?', '["16.6604 and 16.9510 volume percent.", "16.2860 and 19.3849 volume percent.", "16.1124 and 16.7449 volume percent.", "16.1124 and 18.7143 volume percent."]'::jsonb, 2, 'The default table reads Kerosene / Jet 16.1124 and Diesel / Gasoil 16.7449. 16.6604 and 16.9510 are the Kwale blend on the same default cuts, 16.2860 and 19.3849 the Kwale blend on Kwale''s cuts, and 18.7143 the default pair''s Vacuum residue.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The studio''s default table shows Vacuum gasoil at 27.7681 volume percent. The Kwale blend on the studio''s default cuts yields 26.6940. What separates the two figures?', '["The cut set: 27.7681 is on the studio''s default cuts and 26.6940 on the Kwale refinery''s own cuts, which end at atmospheric residue.", "The basis: 27.7681 is the vacuum gasoil yield weighted on mass and 26.6940 the same yield weighted on volume.", "The reading: 27.7681 is read at the first grid point past each cut point and 26.6940 interpolated on the curve.", "The blend: the default pair at 60 and 40 against Kwale Light and Ughelli Medium at 55 and 45, on the same default cuts."]'::jsonb, 3, 'The default table is the studio''s default pair on its default cuts. The Kwale blend on the same default cuts, a vacuum refinery''s cut set, yields 26.6940 percent vacuum gasoil.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'In what order does the Kwale valuation run from the two crudes to the differential?', '["Blend the crudes'' T50 on volume, draw the cut yields from that T50, price the cuts, subtract the costs, then take the loss and set the result against the marker.", "Blend the curve on volume, cut it into yields, price the cuts, take the loss off the product value, subtract the costs, then set the netback against the marker.", "Blend the curve on mass, cut it into yields, subtract processing and freight from each product price, take the loss, then set the netback against the marker.", "Blend the curve on volume, price the cuts, subtract processing and freight, take the loss off what remains, then set the netback against the marker."]'::jsonb, 1, 'The blend''s curve is formed on volume and the cut yields are read off it; the loss comes off the product value before processing and freight; the differential is the netback minus the marker''s 72.5 $/bbl.'),
  ('crude', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which figures of the Kwale valuation did module 4 build, and on what rule?', '["The gross of 74.2412, the loss value of 0.5939 and the netback of 64.9473 $/bbl, with the loss taken on the product side before the costs.", "The gross of 74.2412, the loss value of 0.5939 and the differential of -7.5527 $/bbl, with the loss taken after the costs.", "The yields of 20.5591 and 43.0526 and the gross of 74.2412 $/bbl, with the yields weighted on mass before pricing.", "The netback of 64.9473 and the differential of -7.5527 $/bbl, with the marker taken off before the processing cost."]'::jsonb, 0, 'Module 3 built the cut yields and module 5 the differential against the marker of 72.5 $/bbl.'),
  ('crude', 'intermediate', 'final', null, 1, 'Take the 1030 F row of the Kwale table, where Kwale Light has distilled 90.0000 percent and Ughelli Medium 80.0000. Which blend figure sits on that row?', '["92.9219 percent.", "85.5000 percent.", "90.0000 percent.", "74.9677 percent."]'::jsonb, 1, 'The blend at 55 and 45 is the volume-weighted sum of the two at a fixed temperature. 92.9219 is the blend at 1200 F and 74.9677 the blend at 860 F.'),
  ('crude', 'intermediate', 'final', null, 2, 'The studio opens on its default pair, 60 and 40. What does the digest print for the two crudes'' own fifty percent points averaged by volume share, minus the engine''s interpolated T50?', '["-2.9207 F.", "-3.3184 F.", "72.8571 F.", "-5.1429 F."]'::jsonb, 3, 'On the default pair the engine reads T50 at 617.1429 F and the crudes'' T50 averaged by volume share is 612.0000 F; the shortcut table prints that difference as -5.1429 F. Each other option sits in the same table on another row or in another column.'),
  ('crude', 'intermediate', 'final', null, 3, 'The Ebocha partial assay''s last TBP point is 88 at 920. What does its curve say above 920 F?', '["Nothing: its last point is below 100 percent, so the value above it is unknown.", "That it is fully distilled, as the engine takes 100 percent above a last point.", "That it holds at 88 percent, the last value the assay recorded at 920 F.", "That it rises along its last segment''s slope until it reaches 100 percent."]'::jsonb, 0, 'Above a last point at 100 percent everything has distilled; Ebocha''s last point is 88 percent, so the curve says nothing about its heaviest part. The Kwale Light and Ebocha blend stops at 920 F with 85.4516 percent.'),
  ('crude', 'intermediate', 'final', null, 4, 'Ughelli Medium''s assay carries 70 at one temperature. Find that row in the Kwale table: which temperature is it, and what has the blend distilled?', '["720 F, where the blend reads 64.0000 percent.", "650 F, where the blend reads 56.9474 percent.", "860 F, where the blend reads 74.9677 percent.", "1030 F, where the blend reads 85.5000 percent."]'::jsonb, 2, 'Ughelli Medium''s assay carries 70 at 860. 720 F is Kwale Light''s 70 percent point and 650 F is Ughelli Medium''s 50 percent point.'),
  ('crude', 'intermediate', 'final', null, 5, 'Kwale Light and the Ebocha partial assay, 50 and 50, are cut on Kwale''s set. Which fact from the blend''s curve decides that two cuts have no yield?', '["The curve keeps every temperature Kwale Light measured, but Ebocha''s share of the light end is taken as zero, which the cuts refuse.", "The curve keeps only temperatures where both crudes are known, so it starts at 110 F, above the 90 F bound those two cuts need.", "The curve keeps 8 of 11 temperatures, and the engine drops the two lightest cuts whenever a curve loses three points.", "The curve stops at 920 F, below the upper bounds of the two lightest cuts on Kwale''s set."]'::jsonb, 1, 'The blend''s curve runs from 3.5217 percent at 110 F to 85.4516 percent at 920 F; of 11 temperatures it keeps 8. A cut whose bound lies outside that stretch cannot be answered.'),
  ('crude', 'intermediate', 'final', null, 6, 'Why is the blend''s T50 read with temperatureAtVolumePercent, the same function a single crude uses?', '["The engine treats the blend as its lighter crude whenever a temperature is asked of it, so a single crude''s function applies to the blend unchanged.", "temperatureAtVolumePercent averages the crudes'' curves inside itself before it reads a temperature, so the one function serves blends and crudes alike.", "A blend has no curve of its own, so the function is run on each crude and the two answers are weighted.", "blendDistillationCurves gives the blend a curve of its own, so every temperature question about the blend is asked of that curve."]'::jsonb, 3, 'Once the blend has a curve, the same function reads it. For the Kwale blend the engine''s T50 is 587.3184 F.'),
  ('crude', 'intermediate', 'final', null, 7, 'Ughelli Medium''s assay carries 30 at 480. Which Kwale Light and blend figures share that row?', '["43.7500 and 37.5625 percent.", "30.0000 and 37.5625 percent.", "43.7500 and 43.6471 percent.", "50.0000 and 43.6471 percent."]'::jsonb, 0, 'The 480 F row reads Kwale Light 43.7500, Ughelli Medium 30.0000 and the blend 37.5625 percent. 43.6471 and 50.0000 are the blend and Kwale Light at 530 F.'),
  ('crude', 'intermediate', 'final', null, 8, 'What temperature does the engine read off the Kwale blend''s curve at 90 volume percent?', '["1030 F.", "1200 F.", "796.5882 F.", "1133.0737 F."]'::jsonb, 3, 'The engine interpolates on the blend''s own curve, so the answer sits on no measured row. 1030 F and 1200 F are the rows either side, and 796.5882 F is the blend''s 70 percent point.'),
  ('crude', 'intermediate', 'final', null, 9, 'The Kwale blend''s curve reaches 212.2121 F at which volume percent?', '["8.0714 percent.", "14.5833 percent.", "10 percent.", "30 percent."]'::jsonb, 2, 'The digest reads the Kwale blend at 10, 30, 50, 70 and 90 percent: 212.2121, 411.6294, 587.3184, 796.5882 and 1133.0737 F. 8.0714 is the blend at 190 F and 14.5833 at 265 F.'),
  ('crude', 'intermediate', 'final', null, 10, 'The Kwale blend''s curve is read at 10, 30, 50, 70 and 90 percent. Why is each of those five temperatures an interpolation?', '["None of the five is a volume percent that any of the blend''s 14 points reads, so each falls between two points.", "The engine rounds each reading to four decimals, and a rounded figure has to be interpolated back onto the curve.", "Each reading is taken on one crude''s curve and carried to the blend, which needs a line drawn between the two.", "The blend''s points sit at every 10 percent, so a reading between two of them is a line between two points."]'::jsonb, 0, '10 percent lies between the blend''s rows at 190 F (8.0714) and 265 F (14.5833), and 90 percent between 1030 F (85.5000) and 1200 F (92.9219). The engine reads 212.2121 F and 1133.0737 F between them.'),
  ('crude', 'intermediate', 'final', null, 11, 'What does T50 tell a reader about a blend?', '["The mean of the temperatures at which each crude reaches half of its own barrels, weighted by the crudes'' volume shares in the blend.", "The temperature at which the blend''s own curve reaches 50 percent distilled.", "The temperature at which the blend''s vapour pressure reaches half an atmosphere in a closed test cell, the figure a tank farm reads.", "The cut point at which the refinery splits naphtha from kerosene on the blend''s own curve."]'::jsonb, 1, 'temperatureAtVolumePercent(curve, 50) reads the temperature at which the blend''s own curve reaches 50 percent. The studio also takes the blend''s T50 as the boiling temperature in Watson K. For the Kwale blend it is 587.3184 F.'),
  ('crude', 'intermediate', 'final', null, 12, 'How does watsonK combine its two inputs?', '["SG^(1/3) / Tb, with Tb in degrees Rankine.", "Tb^(1/3) x SG, with Tb in degrees F.", "Tb / SG^(1/3), with Tb in degrees F.", "Tb^(1/3) / SG, with Tb in degrees Rankine."]'::jsonb, 3, 'SG is the blend''s specific gravity, blended on volume, 0.8595 for the Kwale blend. Tb is a boiling temperature on the absolute scale, which the studio takes as the blend''s T50.'),
  ('crude', 'intermediate', 'final', null, 13, 'Suppose the Kwale blend''s T50 is read from the grid instead of by interpolation. How far does the error travel?', '["Nowhere past T50, since Watson K is taken at the mean average boiling point.", "Into the cut yields, which the engine draws from the T50 before it cuts the rest of the curve.", "Into Watson K, which reads 12.0447 at the grid reading against 11.8135 at the interpolated T50.", "Into the netback, which the engine scales by the blend''s T50 before it takes processing off."]'::jsonb, 2, 'The grid reading minus the engine is 62.6816 F, and the studio takes Tb in Watson K as the blend''s T50, so the characterisation factor moves with it.'),
  ('crude', 'intermediate', 'final', null, 14, 'Cutting the Kwale blend''s own curve between 330 F and 480 F gives which kerosene figure?', '["16.2860 volume percent.", "16.2136 volume percent.", "18.1944 volume percent.", "16.6604 volume percent."]'::jsonb, 0, '16.2136 is the crude yields weighted by mass fraction, 18.1944 is Kwale Light''s own kerosene, and 16.6604 is the blend''s Kerosene / Jet on the studio''s default cuts.'),
  ('crude', 'intermediate', 'final', null, 15, 'A refinery lifts its diesel cut to end at 700 F. How much of the Kwale blend does Diesel / AGO then take?', '["19.3849 percent of every barrel.", "24.4225 percent of every barrel.", "38.0150 percent of every barrel.", "5.0376 percent of every barrel."]'::jsonb, 1, 'Diesel / AGO gains 5.0376 over its 19.3849 at 650 F, and Atmospheric residue falls to 38.0150.'),
  ('crude', 'intermediate', 'final', null, 16, 'On the studio''s default cut set, how much of the Kwale blend lands in Vacuum residue?', '["18.7143 percent by volume.", "26.6940 percent by volume.", "43.0526 percent by volume.", "16.3586 percent by volume."]'::jsonb, 3, 'The default set splits the heavy end at 1000 F. 26.6940 is the blend''s Vacuum gasoil, 43.0526 its Atmospheric residue on Kwale''s cuts, and 18.7143 the default pair''s Vacuum residue.'),
  ('crude', 'intermediate', 'final', null, 17, 'Which cut set does the digest call a vacuum refinery''s?', '["Kwale''s own cuts, with a single heavy cut from 650 F upward.", "The cut set drawn inside the Ebocha partial curve, from 110 F to 920 F.", "The studio''s default cuts, which split the heavy end at 1000 F.", "Kwale''s cuts with the diesel end point moved from 650 F to 700 F."]'::jsonb, 2, 'The studio''s default cuts are printed on the Kwale blend for contrast as a vacuum refinery''s cut set: Vacuum gasoil runs from 650 F to 1000 F and Vacuum residue from 1000 F with no upper bound.'),
  ('crude', 'intermediate', 'final', null, 18, 'Kwale''s Kerosene / DPK runs from 330 F to 480 F and the default Kerosene / Jet from 350 F to 500 F. Why do the two kerosene yields of the same blend differ?', '["Each covers a different stretch of the same curve, because two boundaries moved.", "The default set weights the kerosene yield on mass, since jet is sold by the tonne.", "The two sets are drawn on different blends, one per refinery''s crude slate.", "The default set normalises its yields to 100 percent after adding a vacuum split."]'::jsonb, 0, 'The Kwale blend yields 16.2860 on Kwale''s kerosene and 16.6604 on the default set''s. Each moved boundary shifts barrels between the two cuts that share it.'),
  ('crude', 'intermediate', 'final', null, 19, 'What are Kwale Light''s and Ughelli Medium''s own Atmospheric residue yields on Kwale''s cuts?', '["43.0526 for Kwale Light and 43.2685 for Ughelli Medium.", "50.0000 for Kwale Light and 37.3684 for Ughelli Medium.", "37.3684 for Kwale Light and 40.1548 for Ughelli Medium.", "37.3684 for Kwale Light and 50.0000 for Ughelli Medium."]'::jsonb, 3, 'The two crude columns are each crude''s own cut yields on Kwale''s cuts. 43.0526 is the blend''s residue and 43.2685 the mass-weighted reading; 40.1548 is the Kwale Light and Ebocha blend''s residue.'),
  ('crude', 'intermediate', 'final', null, 20, 'On the Kwale Light and Ebocha blend, which output names LPG / Light ends and Naphtha as unknownCuts, and which names them as unyieldedCuts?', '["netbackValue names them in unknownCuts, and cutYields names them in unyieldedCuts.", "cutYields names them in both lists, and netbackValue carries the two lists forward.", "cutYields names them in unknownCuts, and netbackValue names them in unyieldedCuts.", "blendDistillationCurves names them in unknownCuts, and cutYields in unyieldedCuts."]'::jsonb, 2, 'The two lists are the same gap seen by two functions. netbackValue keeps their yield and value empty and reports complete: false, with a netback of 48.3393 $/bbl over the cuts it can value.'),
  ('crude', 'intermediate', 'final', null, 21, 'Beside the engine''s 0.7174 for LPG / Light ends, what does blendOnMass print for the Kwale blend?', '["0.7174.", "0.6951.", "1.3043.", "0.4615."]'::jsonb, 1, '0.6951 is the mass-weighted LPG figure. 1.3043 is Kwale Light alone, and 0.4615 is the default pair''s LPG on the studio''s default cuts.'),
  ('crude', 'intermediate', 'final', null, 22, 'Which row of Kwale''s term table belongs to Diesel / AGO?', '["18.9972 $/bbl of crude, from a yield of 19.3849 volume percent at 98 $/bbl of product.", "24.5400 $/bbl of crude, from a yield of 43.0526 volume percent at 57 $/bbl of product.", "18.9972 $/bbl of crude, from a yield of 19.4040 volume percent at 98 $/bbl of product.", "98 $/bbl of crude, the diesel price, taken whole as the value of the cut."]'::jsonb, 0, '24.5400 is the residue''s value. 19.4040 is diesel''s mass-weighted reading (blendOnMass), which the netback does not use.'),
  ('crude', 'intermediate', 'final', null, 23, 'How is the Kwale gross product value of 74.2412 $/bbl of crude formed?', '["It is the mean of the five product prices, weighted by the crudes'' volume shares.", "It is the netback plus the loss value, before processing and freight are added back.", "It is the sum of the five product prices, scaled by the fraction of barrels that close.", "It is the sum of the five cut values, each a yield fraction times its product price."]'::jsonb, 3, 'The five values are 0.3443, 15.2137, 15.1460, 18.9972 and 24.5400 $/bbl of crude. The loss at 0.8 percent comes off after that sum.'),
  ('crude', 'intermediate', 'final', null, 24, 'In the Kwale netback, what are processing cost and freight per?', '["Per barrel of product: 6.8000 and 1.9000 $/bbl.", "Per barrel of crude: 0.5939 and 6.8000 $/bbl.", "Per barrel of crude: 6.8000 and 1.9000 $/bbl.", "Per barrel of crude, each scaled down by the 0.8 percent loss: 6.8000 and 1.9000 $/bbl."]'::jsonb, 2, 'The netback formula ends with minus processing cost minus freight, all per barrel of crude. 0.5939 is the loss term, a different line of the account.'),
  ('crude', 'intermediate', 'final', null, 25, 'Which terms does netbackValue report beside the Kwale netback of 64.9473 $/bbl of crude?', '["None: it reports the total, and the terms are left to the caller.", "Gross 74.2412, loss value 0.5939, processing 6.8000 and freight 1.9000.", "Gross 74.2412, loss value 0.0696, processing 6.8000 and freight 1.9000.", "Gross 74.2412, loss value 0.5939, processing 1.9000 and freight 6.8000."]'::jsonb, 1, 'Every term is reported beside the total: gross product value 74.2412, value lost to losses at 0.8 percent 0.5939, processing cost 6.8000 and freight 1.9000 $/bbl of crude. 0.0696 is how far the after-the-costs reading lands from the engine.'),
  ('crude', 'intermediate', 'final', null, 26, 'Under the complete Kwale valuation the digest prints: Costs taken as zero because they were blank: nothing. What does that line confirm?', '["assumedZero is empty, so the netback of 64.9473 carries no assumed zero.", "Every cut had a price, so unpricedCuts is empty and the valuation is complete.", "Every cost was refused and none entered the netback of 64.9473.", "The loss was taken on the product side, so no cost was reduced by it."]'::jsonb, 0, 'A cost left blank would be taken as zero and named, as freight and losses are in the 67.4412 $/bbl case. Complete: true is the separate line about prices and yields.'),
  ('crude', 'intermediate', 'final', null, 27, 'What is the netback of 64.9473 $/bbl a measure of?', '["What a barrel of the Kwale blend sells for at the loading terminal before any refinery bids, set by the marker and the blend''s API.", "What the Kwale refinery earns on each barrel of product it sells from the blend, after the product-side losses and before its own costs.", "What a barrel of the Kwale blend is worth against the marker crude, the figure a trader quotes when offering the blend at the refinery.", "What a barrel of the Kwale blend is worth at the Kwale refinery, once its products are valued and losses, processing and freight come off."]'::jsonb, 3, 'netback = sum(cut yield fraction x cut product price) x (1 - loss percent / 100) - processing cost - freight, all per barrel of crude. The differential against the marker is a separate figure, -7.5527 $/bbl.'),
  ('crude', 'intermediate', 'final', null, 28, 'Which cut of the Kwale blend is priced at 48 $/bbl of product, and what is it worth per barrel of crude?', '["LPG / Light ends, 0.7174 $/bbl of crude.", "Naphtha, 15.2137 $/bbl of crude.", "LPG / Light ends, 0.3443 $/bbl of crude.", "Atmospheric residue, 24.5400 $/bbl of crude."]'::jsonb, 2, 'The LPG / Light ends row reads a yield of 0.7174 volume percent, a price of 48 $/bbl of product and a value of 0.3443 $/bbl of crude. Naphtha is priced at 74 and Atmospheric residue at 57.'),
  ('crude', 'intermediate', 'final', null, 29, 'Which of the three rows valued against Kwale''s marker carries a differential of -8.8324 $/bbl?', '["Kwale Light alone, netting back 65.9944 $/bbl.", "Ughelli Medium alone, netting back 63.6676 $/bbl.", "The blend at 55 and 45, netting back 64.9473 $/bbl.", "Ughelli Medium alone, netting back 72.9512 $/bbl."]'::jsonb, 1, 'Each differential is that row''s netback minus 72.5. 72.9512 is Ughelli Medium''s gross, before the loss and the costs.'),
  ('crude', 'intermediate', 'final', null, 30, 'What is Kwale''s marker of 72.5 $/bbl?', '["The marker netback netbackValue sets each crude''s netback against.", "A published market price for a real grade, entered as the reference crude.", "The volume-weighted mean of the two crudes'' netbacks at 55 and 45.", "The Kwale blend''s gross product value before the loss and the costs."]'::jsonb, 0, 'netbackValue takes a marker netback and reports the differential: this crude''s netback minus the marker''s. Like every figure in the course, 72.5 is invented. 64.9473 is the volume-weighted mean of the two crudes'' netbacks and 74.2412 the blend''s gross.'),
  ('crude', 'intermediate', 'final', null, 31, 'What does the digest print as the first point of the default pair''s blend curve at or past 50 percent?', '["650 F.", "617.1429 F.", "614.2222 F.", "690 F."]'::jsonb, 3, 'The shortcut table prints the default pair''s grid reading minus the engine as 72.8571 F, the grid reading being 690 F. The Kwale blend''s grid reading is 650 F. The other two options are the default pair''s own interpolated and mass-weighted readings.'),
  ('crude', 'intermediate', 'final', null, 32, 'With nothing typed, the Crude Assay & Blending Studio values its default pair on its default cuts. Which gross product value and netback does it show?', '["Gross 74.2412 and netback 64.9473 $/bbl.", "Gross 75.2968 and netback 65.9944 $/bbl.", "Gross 76.6165 and netback 69.7334 $/bbl.", "Gross 72.9512 and netback 63.6676 $/bbl."]'::jsonb, 2, 'The studio''s default table prints gross product value 76.6165 and netback 69.7334 $/bbl. 74.2412 and 64.9473 are the Kwale blend''s, 75.2968 and 65.9944 Kwale Light''s alone, and 72.9512 and 63.6676 Ughelli Medium''s alone.'),
  ('crude', 'intermediate', 'final', null, 33, 'What kind of test is D86, and how is a crude assay reported?', '["D86 is the crude assay test; TBP is kept for finished products.", "D86 is a product test; a crude assay is reported as a TBP distillation.", "D86 is a product test; a crude assay is reported as a D86 curve converted by d86ToTbp.", "D86 is a crude assay test that d86ToTbp converts with its own table."]'::jsonb, 1, 'The digest: D86 is a product test; a crude assay is reported as a TBP distillation. d86ToTbp ships no coefficient table, and called without one it refuses.'),
  ('crude', 'intermediate', 'final', null, 34, 'Why does d86ToTbp ship no coefficient table for API Technical Data Book Procedure 3A1.1?', '["Reproducing a published table from memory is something the engines refuse to do.", "The table is proprietary to each refinery, calibrated on its own D86 runs.", "The conversion needs no table once the 50 percent point is known.", "The table applies only to products, and cutYields would refuse a converted crude."]'::jsonb, 0, 'd86ToTbp has the structure of the cut-point-difference conversion. Called without the table it refuses and names two ways forward: supply it, or enter the assay as a TBP distillation.'),
  ('crude', 'intermediate', 'final', null, 35, 'Kwale Light''s gross product value alone is 75.2968 $/bbl. What is it formed from?', '["The blend''s cut yields on Kwale''s cuts, such as 20.5591 naphtha, weighted up by Kwale Light''s volume share of 55.", "Kwale Light''s own cut yields on the studio''s default cuts, each times the default price for that product.", "Kwale Light''s own cut yields weighted by mass fraction, each times Kwale''s price for that product.", "Kwale Light''s own cut yields on Kwale''s cuts, such as 24.2512 naphtha, each times Kwale''s price for that product."]'::jsonb, 3, 'Kwale Light''s naphtha of 24.2512 at 74 and its residue of 37.3684 at 57 are two of its five pairings. The blend''s own naphtha, 20.5591, belongs to the blend''s gross of 74.2412.'),
  ('crude', 'intermediate', 'final', null, 36, 'Which rule from module 1 lies at the root of the 0.0000 between the Kwale blend''s netback and the volume-weighted mean of its crudes'' netbacks?', '["Temperatures are weighted on mass.", "A blank cost is taken as zero.", "Yields are additive on volume.", "A blend''s curve keeps every row."]'::jsonb, 2, 'Because yields add on volume, the blend''s cut yields equal the volume-weighted crude yields, and the gross, the loss and the per-barrel costs keep that weighting through to the netback.'),
  ('crude', 'intermediate', 'final', null, 37, 'Which of these printed differences shows a shortcut that fails?', '["The volume-weighted crude yields minus the blend''s cut yields, 0.0000 on every cut.", "The volume-weighted mean of the crudes'' T50 minus the engine, -3.3184 F.", "The blend''s netback minus the volume-weighted mean of its crudes'' netbacks, 0.0000.", "The change in the total when the diesel end moves to 700 F, 0.0000."]'::jsonb, 1, 'Yields add on volume, so the cut yields and the netback each match their volume-weighted readings at 0.0000. The volume-weighted mean of the crudes'' T50 minus the engine''s 587.3184 F is -3.3184 F. The diesel end point is a cut point moving, which is no shortcut.'),
  ('crude', 'intermediate', 'final', null, 38, 'What blend API does the studio show when it opens on its default pair, 60 and 40?', '["30.6451.", "33.1219.", "32.8173.", "29.3808."]'::jsonb, 0, 'The default table prints blend API 30.6451. 33.1219 is the Kwale blend''s API, 32.8173 the Associate tier''s Obigbo export blend and 29.3808 its 20 and 40 API pair at 50 and 50.'),
  ('crude', 'intermediate', 'final', null, 39, 'Segment overlap is one of the oracle''s roads. Which figure does it reach that way, and what is the engine''s road to the same figure?', '["The blend''s T50: the oracle measures how much of each straight segment lies below 50 percent, where the engine interpolates between the two points either side.", "The netback: the oracle overlaps the product segments with the cargo''s barrels, where the engine sums yield fractions times prices and takes off the costs.", "The mass fractions: the oracle overlaps each crude''s barrels with its pounds, where the engine converts volume shares to mass shares with a formula.", "A cut''s yield: the oracle measures each segment''s overlap with the cut, where the engine takes the curve at the upper bound minus the lower."]'::jsonb, 3, 'The oracle takes yields by segment overlap. cutYields returns each cut''s yield as the curve at the cut''s upper bound minus the curve at its lower bound. The oracle finds T50 by bisection and loads a cargo in barrels and pounds.'),
  ('crude', 'intermediate', 'final', null, 40, 'How does the oracle recover a viscosity from a Refutas index?', '["By viscosityFromBlendIndex, the engine''s own inversion, run inside the oracle.", "By averaging the crudes'' viscosities linearly on mass fraction and reading the index off that average.", "By bisection, halving an interval until the viscosity whose index matches is closed in on.", "By blending the index on volume fractions, as ASTM D7152 does, then inverting it."]'::jsonb, 2, 'The engine inverts the index directly with viscosityFromBlendIndex. The oracle searches for it, so the two roads are independent.'),
  ('crude', 'intermediate', 'final', null, 41, 'One cut of the Kwale blend contributes 15.1460 $/bbl of crude. Which cut, from which yield and price?', '["Naphtha, 20.5591 volume percent at 74 $/bbl of product.", "Kerosene / DPK, 16.2860 volume percent at 93 $/bbl of product.", "Kerosene / DPK, 16.2136 volume percent at 93 $/bbl of product.", "Diesel / AGO, 19.3849 volume percent at 98 $/bbl of product."]'::jsonb, 1, 'Kerosene / DPK is worth 15.1460 $/bbl of crude. Naphtha is worth 15.2137 and Diesel / AGO 18.9972. 16.2136 is kerosene''s mass-weighted reading, which the netback does not use.'),
  ('crude', 'intermediate', 'final', null, 42, 'The Kwale blend, 55 and 45, prints API 33.1219 and sulfur 0.2268 wt%. Which SG sits beside them, the SG that Watson K divides by?', '["0.8595.", "0.8727.", "0.8328.", "0.8922."]'::jsonb, 0, 'The digest prints Blend API 33.1219, SG 0.8595, sulfur 0.2268 wt% (mass basis). 0.8727 is the studio''s default pair''s SG, 0.8328 Kwale Light''s and 0.8922 Ughelli Medium''s.');
